# November 19, 2026: southeast Saskatchewan: the Qu'Appelle Valley (Fort Qu'Appelle, Lebret, Katepwa, Qu'Appelle,
# Abernethy), Wolseley, the Moose Mountain country (Cannington Manor), the lower Qu'Appelle (Fort Espérance, Esterhazy),
# Estevan, and the Claybank Brick Plant south of Moose Jaw. Region sk drawn at random by tools/choose.py --claim.
# Sources were opened in this session: the Canadian Register of Historic Places (historicplaces.ca) statement for every
# place, read whole with tools/page.py --all; Wikipedia as raw text (tools/wiki_raw.py); Parks Canada's Motherwell and
# Fort Espérance visit pages; the Museums Association of Saskatchewan listings (Claybank, Fort Qu'Appelle, Esterhazy,
# Estevan); claybankbrick.ca; the National Trust for Canada's Claybank page (via Canada's History); the Town of Wolseley,
# Town of Esterhazy and Tourism Saskatchewan pages; the Sask Parks Cannington Manor driving-tour brochure (PDF); the
# Encyclopedia of Saskatchewan; the Catholic Register and Grasslands News on Lebret. Sask Parks' own park pages and
# Parks Canada's hours pages are drawn by script and could not be read.
from data_b import N
from data_ma import W
def L(t,u): return [t,u]
def HP(t,i): return ['Canadian Register of Historic Places: '+t,'https://www.historicplaces.ca/en/rep-reg/place-lieu.aspx?id=%d'%i]
